import{_ as t,o,c as a,a2 as n}from"./chunks/framework.BfWdyVj4.js";const m=JSON.parse('{"title":"Good morning","description":"","frontmatter":{},"headers":[],"relativePath":"features/good-morning.md","filePath":"features/good-morning.md","lastUpdated":1793115182000}'),s={name:"features/good-morning.md"};function i(r,e,h,d,g,l){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="good-morning" tabindex="-1">Good morning <a class="header-anchor" href="#good-morning" aria-label="Permalink to &quot;Good morning&quot;">​</a></h1><p>The other end of <a href="/features/goodnight">Goodnight</a>: at a time you pick, a display wakes its room up.</p><ul><li><strong>The lights fade up</strong>, like a sunrise, over the minutes before the time (15 by default, up to 80%), using the lights&#39; own transitions in Home Assistant.</li><li><strong>At the time</strong>, night mode ends, the screen lights up, and the frog says good morning to whoever the display is for: the time, the weather now and today&#39;s high (and if rain is on the way), and the day&#39;s events from any calendars you picked. A card shows the same.</li></ul><p>It happens once a day, and still happens up to half an hour late if the tablet was asleep or restarting at the time.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Each display has its own, under <strong>Settings → Good morning</strong>: on or off, the time, which days (weekdays, weekends or every day), the lights (fade up, how long and how bright, or leave them), whether to speak, and which Home Assistant calendars to read today&#39;s events from (none until you tick them, so private calendars stay private).</p><p>The lights need the grown-ups&#39; <strong>devices</strong> switch, as with Goodnight.</p>',7)])])}const u=t(s,[["render",i]]);export{m as __pageData,u as default};
